import pandas as pd

def server_utilization_time(servers: pd.DataFrame) -> pd.DataFrame:
    df = servers.copy()
    if df.empty:
        return pd.DataFrame({'total_uptime_days': [0]})
    df['status_time'] = pd.to_datetime(df['status_time'])
    df = df.sort_values(by=['server_id', 'status_time'])
    df['next_status_time'] = df.groupby('server_id')['status_time'].shift(-1)

    starts = df[df['session_status'] == 'start']
    total_seconds = (starts['next_status_time'] - starts['status_time']).dt.total_seconds().sum()
    days = int(total_seconds // 86400) if not pd.isna(total_seconds) else 0
    return pd.DataFrame({'total_uptime_days': [days]})
